INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(398262, 34897, 7969, '<td valign="top">Well, I think photographically this shot is not great, but I love your title and the statement you are making.</td>', 'Well, I think photographically this shot is not great, but I love your title and the statement you are making.', '2003-08-25 01:10:23.000000', NULL, 1),
(398267, 34612, 10673, '<td valign="top">Beautifully done!  Bravo!</td>', 'Beautifully done!  Bravo!', '2003-08-25 01:14:34.000000', NULL, 1),
(398271, 34900, 5082, '<td valign="top">The image apepars to tilt ever so slightly to the right due to the chosen perspective, I like the sun flare, it adds something to the photo, I hope you don''t get roasted for it. Good Luck.</td>', 'The image apepars to tilt ever so slightly to the right due to the chosen perspective, I like the sun flare, it adds something to the photo, I hope you don''t get roasted for it. Good Luck.', '2003-08-25 01:18:03.000000', NULL, 1),
(398274, 34727, 10673, '<td valign="top">Excellent lighting, clarity &amp; composition!  Bravo!</td>', 'Excellent lighting, clarity & composition!  Bravo!', '2003-08-25 01:19:36.000000', NULL, 1),
(398275, 34318, 5082, '<td valign="top">I have driven past this monument for all of my life, but I have never seen it the way it was captured here.  Great lines, the sky is wonderful.  Good Luck.</td>', 'I have driven past this monument for all of my life, but I have never seen it the way it was captured here.  Great lines, the sky is wonderful.  Good Luck.', '2003-08-25 01:19:51.000000', NULL, 1),
(398276, 34861, 5082, '<td valign="top">You might get dinged for the noise in this photo, I am assuming you are shooting with a smaller megapixel cam so something like Neat Image might help you... but your composition is very very good, and you chose a great time of day to shoot the monument.</td>', 'You might get dinged for the noise in this photo, I am assuming you are shooting with a smaller megapixel cam so something like Neat Image might help you... but your composition is very very good, and you chose a great time of day to shoot the monument.', '2003-08-25 01:21:46.000000', NULL, 1),
(398277, 34877, 5082, '<td valign="top">Great shot, good use of a shallow DOF to make an interesting background.</td>', 'Great shot, good use of a shallow DOF to make an interesting background.', '2003-08-25 01:23:07.000000', NULL, 1),
(398278, 34553, 10673, '<td valign="top">Unusual angle...love it!</td>', 'Unusual angle...love it!', '2003-08-25 01:23:46.000000', NULL, 1),
(398279, 34763, 4338, '<td valign="top">I like the composition an the subject. I feel it would look better is the sky was a darker blue, the image looks a little over exposed.</td>', 'I like the composition an the subject. I feel it would look better is the sky was a darker blue, the image looks a little over exposed.', '2003-08-25 01:24:06.000000', NULL, 1),
(398282, 34789, 9854, '<td valign="top">The title is a bit foreboding. I hope it won''t repeat in 2003!!</td>', 'The title is a bit foreboding. I hope it won''t repeat in 2003!!', '2003-08-25 01:24:37.000000', NULL, 1),
(398283, 34900, 4338, '<td valign="top">very well done, I like all the aspects of this image !!!!! a 10</td>', 'very well done, I like all the aspects of this image !!!!! a 10', '2003-08-25 01:25:23.000000', NULL, 1),
(398284, 34666, 4493, '<td valign="top">Perfect! 10 -danny</td>', 'Perfect! 10 -danny', '2003-08-25 01:25:54.000000', NULL, 1),
(398285, 34532, 10673, '<td valign="top">Very well done...great lighting, composition &amp; atmosphere!</td>', 'Very well done...great lighting, composition & atmosphere!', '2003-08-25 01:26:27.000000', NULL, 1),
(398286, 34414, 10673, '<td valign="top">Fantastic!  Love the close crop!</td>', 'Fantastic!  Love the close crop!', '2003-08-25 01:27:17.000000', NULL, 1),
(398288, 34891, 10673, '<td valign="top">Well done!  Bravo!</td>', 'Well done!  Bravo!', '2003-08-25 01:29:33.000000', NULL, 1),
(398290, 34820, 4338, '<td valign="top">i like the composition and the subject , however i feel it is a little too bright on the left hand side</td>', 'i like the composition and the subject , however i feel it is a little too bright on the left hand side', '2003-08-25 01:29:50.000000', NULL, 1),
(398291, 34877, 4493, '<td valign="top">Wow! Stunning! 10 -danny</td>', 'Wow! Stunning! 10 -danny', '2003-08-25 01:30:18.000000', NULL, 1),
(398293, 34773, 4338, '<td valign="top">very nicely done.....</td>', 'very nicely done.....', '2003-08-25 01:30:51.000000', NULL, 1),
(398295, 34899, 10673, '<td valign="top">Absolutely awesome!  An award winner for sure!  10</td>', 'Absolutely awesome!  An award winner for sure!  10', '2003-08-25 01:32:45.000000', NULL, 1),
(398296, 34556, 10673, '<td valign="top">Great old monument...very well done!  Bravo!</td>', 'Great old monument...very well done!  Bravo!', '2003-08-25 01:33:39.000000', NULL, 1),
(398297, 34893, 10673, '<td valign="top">Great angle, use of light, clarity &amp; composition!  Well done...bravo!</td>', 'Great angle, use of light, clarity & composition!  Well done...bravo!', '2003-08-25 01:36:23.000000', NULL, 1),
(398300, 34889, 4338, '<td valign="top">maybe a little lower angle from the ground up would have made a stronger image, also a little later time in the day to get a not so bright sky would have been nice.</td>', 'maybe a little lower angle from the ground up would have made a stronger image, also a little later time in the day to get a not so bright sky would have been nice.', '2003-08-25 01:38:48.000000', NULL, 1),
(398302, 34318, 1717, '<td valign="top">this is stunning!  every element works perfectly...lighting, composition, negative space, textures...i don''t see how it could be any better!  gorgeous moire pattern in the clouds, too.  simply beautiful...10</td>', 'this is stunning!  every element works perfectly...lighting, composition, negative space, textures...i don''t see how it could be any better!  gorgeous moire pattern in the clouds, too.  simply beautiful...10', '2003-08-25 01:40:57.000000', NULL, 1),
(398303, 34817, 4338, '<td valign="top">nice composition with the palm tree in the backround.</td>', 'nice composition with the palm tree in the backround.', '2003-08-25 01:41:15.000000', NULL, 1),
(398304, 34559, 4338, '<td valign="top">image looks a little over edited, but the subject is very interesting</td>', 'image looks a little over edited, but the subject is very interesting', '2003-08-25 01:43:19.000000', NULL, 1),
(398305, 34665, 10673, '<td valign="top">Beautiful...great angle, use of light &amp; composition!  Bravo!</td>', 'Beautiful...great angle, use of light & composition!  Bravo!', '2003-08-25 01:43:50.000000', NULL, 1),
(398308, 34659, 10673, '<td valign="top">Beautifully done!  Great composition, use of light and clarity.  Bravo!</td>', 'Beautifully done!  Great composition, use of light and clarity.  Bravo!', '2003-08-25 01:47:08.000000', NULL, 1),
(398318, 34900, 6008, '<td valign="top">So many things to like in this image. The black and white is great, adds a nice moody feel. The light wisps of clouds gives it an ethereal feel. The composition is good, even centered. And you gotta love the light glare on the edge of the structure. A great homage to a great musician, and a great photograph!</td>', 'So many things to like in this image. The black and white is great, adds a nice moody feel. The light wisps of clouds gives it an ethereal feel. The composition is good, even centered. And you gotta love the light glare on the edge of the structure. A great homage to a great musician, and a great photograph!', '2003-08-25 02:02:25.000000', NULL, 1),
(398319, 34532, 10643, '<td valign="top">This would also have been a beautiful entry in The Past. It reminds me of the poem "Ozymandias" where it says "the lone and level sands stretch far away." Lovely.</td>', 'This would also have been a beautiful entry in The Past. It reminds me of the poem "Ozymandias" where it says "the lone and level sands stretch far away." Lovely.', '2003-08-25 02:04:32.000000', NULL, 1),
(398320, 34877, 6008, '<td valign="top">I think the background really makes this image. The monument is great, dont get me wrong here, and the crop, which doesnt seem to work at first, actually doesnt really do anything too negative to the image, but coupled with the background it really tells a story.</td>', 'I think the background really makes this image. The monument is great, dont get me wrong here, and the crop, which doesnt seem to work at first, actually doesnt really do anything too negative to the image, but coupled with the background it really tells a story.', '2003-08-25 02:05:12.000000', NULL, 1),
(398323, 34665, 6008, '<td valign="top">The deep color in the sky really makes this image, I think. The drama of the sky added to the statue''s pose and having him seemingly look at the tops of the trees all nicely tie together well.</td>', 'The deep color in the sky really makes this image, I think. The drama of the sky added to the statue''s pose and having him seemingly look at the tops of the trees all nicely tie together well.', '2003-08-25 02:09:03.000000', NULL, 1),
(398326, 34863, 6565, '<td valign="top">I particularly like how the wings are practically invisible except in shadow!  This is a very nice image!</td>', 'I particularly like how the wings are practically invisible except in shadow!  This is a very nice image!', '2003-08-25 02:15:01.000000', NULL, 1),
(398327, 34875, 6008, '<td valign="top">Compositionally this is great, the image is very appealing, and I love the warm tones. Architecture and nature combined in a wonderful harmony. The only negative is something you likely couldnt control and is more of an observance than a noted flaw, but it''s a shame you couldnt have obscured the lights behind the trees.</td>', 'Compositionally this is great, the image is very appealing, and I love the warm tones. Architecture and nature combined in a wonderful harmony. The only negative is something you likely couldnt control and is more of an observance than a noted flaw, but it''s a shame you couldnt have obscured the lights behind the trees.', '2003-08-25 02:17:24.000000', NULL, 1),
(398329, 34889, 6008, '<td valign="top">Wow, the detail on this is quite amazing. It''s very clear, sharp, and intricate! It''s a center placement, but it looks good, nicely framed on either side by the trees. The colors are very vibrant, and the slight glow on the statue itself is good, although had it been a little more widespread and really shone it may have been even better. I like the fact that you used a part of the base too instead of just cropping the statue. Wonderful image.</td>', 'Wow, the detail on this is quite amazing. It''s very clear, sharp, and intricate! It''s a center placement, but it looks good, nicely framed on either side by the trees. The colors are very vibrant, and the slight glow on the statue itself is good, although had it been a little more widespread and really shone it may have been even better. I like the fact that you used a part of the base too instead of just cropping the statue. Wonderful image.', '2003-08-25 02:20:19.000000', NULL, 1),
(398331, 34899, 11073, '<td valign="top">GREAT shadows!</td>', 'GREAT shadows!', '2003-08-25 02:25:08.000000', NULL, 1),
(398333, 34889, 11073, '<td valign="top">nice shot - way to frame it w/ the trees.</td>', 'nice shot - way to frame it w/ the trees.', '2003-08-25 02:26:52.000000', NULL, 1),
(398334, 34867, 11073, '<td valign="top">very cool</td>', 'very cool', '2003-08-25 02:27:14.000000', NULL, 1),
(398335, 34666, 8054, '<td valign="top">Excellent tonal balance and detail! Only down side: what is this statue a function/part of? I guess it''s not really a necessity.</td>', 'Excellent tonal balance and detail! Only down side: what is this statue a function/part of? I guess it''s not really a necessity.', '2003-08-25 02:28:40.000000', NULL, 1),
(398336, 34873, 11073, '<td valign="top">great shot. i love how the water gives a sense of "movement" to the pic. good eye to capture that so efectively.</td>', 'great shot. i love how the water gives a sense of "movement" to the pic. good eye to capture that so efectively.', '2003-08-25 02:28:49.000000', NULL, 1),
(398338, 34909, 11073, '<td valign="top">very cool pic. the use of lighting is wonderful. filter for the clouds? they look great.</td>', 'very cool pic. the use of lighting is wonderful. filter for the clouds? they look great.', '2003-08-25 02:30:52.000000', NULL, 1),
(398339, 34654, 8054, '<td valign="top">Good use of natural light. Angle give a sense of size.</td>', 'Good use of natural light. Angle give a sense of size.', '2003-08-25 02:31:29.000000', NULL, 1),
(398341, 34727, 11073, '<td valign="top">oldy, but a goody :) nice pic. very well composed, and good lighting.</td>', 'oldy, but a goody :) nice pic. very well composed, and good lighting.', '2003-08-25 02:33:09.000000', NULL, 1),
(398342, 34676, 8054, '<td valign="top">Maybe this could have been photographed from a different angle. The subject matter is excellent but I''m not moved by the angle at which it was taken.</td>', 'Maybe this could have been photographed from a different angle. The subject matter is excellent but I''m not moved by the angle at which it was taken.', '2003-08-25 02:33:11.000000', NULL, 1),
(398343, 34900, 8054, '<td valign="top">Cloud pattern is amazing and creates an aura around the monuument. Too bad the contrast is lacking making the image appear flat.</td>', 'Cloud pattern is amazing and creates an aura around the monuument. Too bad the contrast is lacking making the image appear flat.', '2003-08-25 02:35:12.000000', NULL, 1),
(398344, 34864, 11073, '<td valign="top">great shot. I like the interpretation of the category - adding style and color in the forefront - while still capturing the essence of the cat. in the background. nice work.</td>', 'great shot. I like the interpretation of the category - adding style and color in the forefront - while still capturing the essence of the cat. in the background. nice work.', '2003-08-25 02:35:39.000000', NULL, 1),
(398347, 34909, 8054, '<td valign="top">Oh wow, this is amazing! Almost a 10 because I feel that there could have been a bit more contrast in the clouds. I give it a 9. Good job!</td>', 'Oh wow, this is amazing! Almost a 10 because I feel that there could have been a bit more contrast in the clouds. I give it a 9. Good job!', '2003-08-25 02:39:31.000000', NULL, 1),
(398348, 34903, 11073, '<td valign="top">good picture. the children playing convey the emotion of what the men were fighting for - nicely captured in the title.  The right side of the monument has an almost curving shape of light that leads your eyes from the top around to the children running in the very same direction your eyes are going. nice. good work.</td>', 'good picture. the children playing convey the emotion of what the men were fighting for - nicely captured in the title.  The right side of the monument has an almost curving shape of light that leads your eyes from the top around to the children running in the very same direction your eyes are going. nice. good work.', '2003-08-25 02:40:26.000000', NULL, 1),
(398349, 34687, 11073, '<td valign="top">:) like the interpretation of the category...cheers!</td>', ':) like the interpretation of the category...cheers!', '2003-08-25 02:41:07.000000', NULL, 1),
(398351, 34823, 8054, '<td valign="top">Very impressive image!</td>', 'Very impressive image!', '2003-08-25 02:42:23.000000', NULL, 1),
(398352, 34507, 8054, '<td valign="top">Good image but it seems to be a bit out of focus and over exposed.</td>', 'Good image but it seems to be a bit out of focus and over exposed.', '2003-08-25 02:43:50.000000', NULL, 1),
(398353, 34891, 11073, '<td valign="top">nice pic...too bad you can''t photoshop out the people in the front :)...but still a cool pic nonetheless. nice job.</td>', 'nice pic...too bad you can''t photoshop out the people in the front :)...but still a cool pic nonetheless. nice job.', '2003-08-25 02:44:38.000000', NULL, 1),
(398354, 34221, 11073, '<td valign="top">great use of light. very cool pic.</td>', 'great use of light. very cool pic.', '2003-08-25 02:45:15.000000', NULL, 1),
(398355, 34883, 11005, '<td valign="top">Am I the only one who sees....I mean, doesn''t that look like...uh...nevermind.  Good shot.</td>', 'Am I the only one who sees....I mean, doesn''t that look like...uh...nevermind.  Good shot.', '2003-08-25 02:45:33.000000', NULL, 1),
(398356, 34889, 8054, '<td valign="top">Whoa boy. This image is making it tough.  :) Excellent work!</td>', 'Whoa boy. This image is making it tough.  :) Excellent work!', '2003-08-25 02:45:46.000000', NULL, 1),
(398358, 34646, 11073, '<td valign="top">awesome shot. love it. the angle give the shot a sense of motion - love it. nice work.</td>', 'awesome shot. love it. the angle give the shot a sense of motion - love it. nice work.', '2003-08-25 02:47:54.000000', NULL, 1),
(398359, 34778, 11073, '<td valign="top">very nice.</td>', 'very nice.', '2003-08-25 02:50:15.000000', NULL, 1),
(398360, 34915, 11073, '<td valign="top">cool shot.</td>', 'cool shot.', '2003-08-25 02:52:47.000000', NULL, 1),
(398361, 34659, 11073, '<td valign="top">really cool subject. where is this?</td>', 'really cool subject. where is this?', '2003-08-25 02:53:59.000000', NULL, 1),
(398362, 34898, 11073, '<td valign="top">cool pic.</td>', 'cool pic.', '2003-08-25 02:54:25.000000', NULL, 1),
(398363, 34115, 11073, '<td valign="top">great use of light and angle of composition. nice pic.</td>', 'great use of light and angle of composition. nice pic.', '2003-08-25 02:55:26.000000', NULL, 1),
(398366, 34401, 8054, '<td valign="top">Funny that someone took a picture of this and entered it. I *almost* took a picture of "CHINATOWNLAND" today! :D</td>', 'Funny that someone took a picture of this and entered it. I *almost* took a picture of "CHINATOWNLAND" today! :D', '2003-08-25 02:57:06.000000', NULL, 1),
(398367, 34832, 11073, '<td valign="top">really cool shot. I like how you use the full frame - most people ( probably including me) would have used the entire statue in the shot...i like how you didn''t. nice work.</td>', 'really cool shot. I like how you use the full frame - most people ( probably including me) would have used the entire statue in the shot...i like how you didn''t. nice work.', '2003-08-25 02:57:33.000000', NULL, 1),
(398368, 34532, 8054, '<td valign="top">Good subject but a very tonally flat image.</td>', 'Good subject but a very tonally flat image.', '2003-08-25 02:58:17.000000', NULL, 1),
(398369, 34538, 11073, '<td valign="top">wow. awesome shot. love the composition and the light. nice work.</td>', 'wow. awesome shot. love the composition and the light. nice work.', '2003-08-25 02:58:30.000000', NULL, 1),
(398370, 34877, 11073, '<td valign="top">very cool. nice depth of field. the scoreboard is the perfect backdrop too - good eye.</td>', 'very cool. nice depth of field. the scoreboard is the perfect backdrop too - good eye.', '2003-08-25 02:59:10.000000', NULL, 1),
