(398373, 34563, 11073, '<td valign="top">nice depth of field.</td>', 'nice depth of field.', '2003-08-25 03:00:07.000000', NULL, 1),
(398376, 34748, 11073, '<td valign="top">cool.  I love how the light is between the two "towers". great use of light. cool pic.</td>', 'cool.  I love how the light is between the two "towers". great use of light. cool pic.', '2003-08-25 03:01:08.000000', NULL, 1),
(398379, 34429, 11073, '<td valign="top">nice depth of field. cool shot.</td>', 'nice depth of field. cool shot.', '2003-08-25 03:02:17.000000', NULL, 1),
(398380, 34368, 11073, '<td valign="top">VERY cool interpretation of category....and a great shot. nice work.</td>', 'VERY cool interpretation of category....and a great shot. nice work.', '2003-08-25 03:03:31.000000', NULL, 1),
(398381, 34443, 11073, '<td valign="top">cool pic. I think the suv in the picture makes it look a little to snap shot...maybe a different angle to cut that out. but still a cool shot nonetheless.</td>', 'cool pic. I think the suv in the picture makes it look a little to snap shot...maybe a different angle to cut that out. but still a cool shot nonetheless.', '2003-08-25 03:05:53.000000', NULL, 1),
(398382, 34665, 11073, '<td valign="top">very cool shot.  I love how you included the tree tops...it give the shot a sense of depth..w/ out them I don''t think that i would have liked it as much. Gives a sense of the "ground" the statue is looking at w/ out showing it. nice work.</td>', 'very cool shot.  I love how you included the tree tops...it give the shot a sense of depth..w/ out them I don''t think that i would have liked it as much. Gives a sense of the "ground" the statue is looking at w/ out showing it. nice work.', '2003-08-25 03:07:59.000000', NULL, 1),
(398383, 34491, 11073, '<td valign="top">love the texture. cool pic.</td>', 'love the texture. cool pic.', '2003-08-25 03:10:51.000000', NULL, 1),
