(398388, 34678, 8054, '<td valign="top">Colors look a bit off (too much red/magenta).</td>', 'Colors look a bit off (too much red/magenta).', '2003-08-25 03:14:13.000000', NULL, 1),
(398389, 34137, 11073, '<td valign="top">great composition.</td>', 'great composition.', '2003-08-25 03:14:53.000000', NULL, 1),
(398390, 34837, 11073, '<td valign="top">awesome shot. love it. depth of field, textures, and colors...oh my :) very cool.</td>', 'awesome shot. love it. depth of field, textures, and colors...oh my :) very cool.', '2003-08-25 03:15:41.000000', NULL, 1),
(398391, 34773, 8054, '<td valign="top">Very cool picture!</td>', 'Very cool picture!', '2003-08-25 03:15:43.000000', NULL, 1),
(398393, 34137, 8054, '<td valign="top">Nice symmetry!</td>', 'Nice symmetry!', '2003-08-25 03:17:05.000000', NULL, 1),
(398394, 34713, 8054, '<td valign="top">I would have voted higher if you blurred the building in the background. That would have really focused the attention on the Chisholm Trail sign.</td>', 'I would have voted higher if you blurred the building in the background. That would have really focused the attention on the Chisholm Trail sign.', '2003-08-25 03:19:22.000000', NULL, 1),
(398396, 34539, 8054, '<td valign="top">Appropriate matter but the angle seems to lack emotion.</td>', 'Appropriate matter but the angle seems to lack emotion.', '2003-08-25 03:21:05.000000', NULL, 1),
(398397, 34221, 8054, '<td valign="top">Very nice! You were able to use the backlighting and illuminate the front of the statue. Good work!</td>', 'Very nice! You were able to use the backlighting and illuminate the front of the statue. Good work!', '2003-08-25 03:22:03.000000', NULL, 1),
(398398, 34806, 8054, '<td valign="top">Great night shot!</td>', 'Great night shot!', '2003-08-25 03:23:26.000000', NULL, 1),
(398399, 34807, 8054, '<td valign="top">Excellent night shot with lots of detail.</td>', 'Excellent night shot with lots of detail.', '2003-08-25 03:24:11.000000', NULL, 1),
(398402, 34874, 8054, '<td valign="top">I know I''m being really picky about this, but I hate it when there are people in the background of my image. Maybe a different angle would have been better.</td>', 'I know I''m being really picky about this, but I hate it when there are people in the background of my image. Maybe a different angle would have been better.', '2003-08-25 03:31:49.000000', NULL, 1),
(398403, 34748, 8054, '<td valign="top">The contrast the dark clouds provide against the mountains is very good. Too bad the dam itself isn''t well lit, too. Overall great image!</td>', 'The contrast the dark clouds provide against the mountains is very good. Too bad the dam itself isn''t well lit, too. Overall great image!', '2003-08-25 03:33:05.000000', NULL, 1),
(398404, 34716, 8054, '<td valign="top">There''s a hint of barrell distortion with the tall building on the right. Not sure if you tried playing with the levels to minimize the effects of haze or not.</td>', 'There''s a hint of barrell distortion with the tall building on the right. Not sure if you tried playing with the levels to minimize the effects of haze or not.', '2003-08-25 03:34:37.000000', NULL, 1),
(398405, 34875, 8054, '<td valign="top">Impressive especially with the sunset and artificial lighting on the dome.</td>', 'Impressive especially with the sunset and artificial lighting on the dome.', '2003-08-25 03:35:19.000000', NULL, 1),
(398406, 34763, 5728, '<td valign="top">I''ve seen this statue before, down Koblenz way on the Rhine right? Good one! Can it be that the statue is tilting a little to the right? Or is it just my eyes this early in the morning? Oh and by the way, you spellt the word "Denkmal" wrong :-)<br/><br/><i>Message edited by author 2003-09-01 06:26:54.</i></td>', 'I''ve seen this statue before, down Koblenz way on the Rhine right? Good one! Can it be that the statue is tilting a little to the right? Or is it just my eyes this early in the morning? Oh and by the way, you spellt the word "Denkmal" wrong :-)', '2003-08-25 03:35:57.000000', '2003-09-01 07:26:54.000000', 1),
