(398715, 34632, 10643, '<td valign="top">nice tight composition, very stark against the sky. I might have liked a person in this shot, up by the columns, to give it more of an idea of scale. I can''t tell from the shot how big this thing is.</td>', 'nice tight composition, very stark against the sky. I might have liked a person in this shot, up by the columns, to give it more of an idea of scale. I can''t tell from the shot how big this thing is.', '2003-08-25 12:58:53.000000', NULL, 1),
(398716, 34727, 10643, '<td valign="top">great sky, and the lighting really makes the spot where the brick changes color stand out (one of my favorite things to point out on the monument).</td>', 'great sky, and the lighting really makes the spot where the brick changes color stand out (one of my favorite things to point out on the monument).', '2003-08-25 13:00:04.000000', NULL, 1),
(398717, 34763, 10643, '<td valign="top">looking forward to the end of the challenge so I can read more about what this is and where!</td>', 'looking forward to the end of the challenge so I can read more about what this is and where!', '2003-08-25 13:00:41.000000', NULL, 1),
(398718, 34909, 10643, '<td valign="top">a very moving and timely choice of a monument, and the dark clouds resembling smoke are an excellent background.</td>', 'a very moving and timely choice of a monument, and the dark clouds resembling smoke are an excellent background.', '2003-08-25 13:01:37.000000', NULL, 1),
(398719, 34368, 11324, '<td valign="top">Very creative use of cu photography</td>', 'Very creative use of cu photography', '2003-08-25 13:01:56.000000', NULL, 1),
(398721, 34911, 10643, '<td valign="top">I like the close-up on the decay of the stone ... brings to mind the passage of time even for things we think of as having permanence and lasting memory.</td>', 'I like the close-up on the decay of the stone ... brings to mind the passage of time even for things we think of as having permanence and lasting memory.', '2003-08-25 13:03:16.000000', NULL, 1),
(398722, 34832, 6870, '<td valign="top">Superb cropping! 9</td>', 'Superb cropping! 9', '2003-08-25 13:03:29.000000', NULL, 1),
(398724, 34789, 6870, '<td valign="top">Wow! How do they know that these people will die in one  month? Amazing! LOL. I like the centered composition here, and the symmetry involved. The sky seems a little light and the statues a little dark, but nice eye for images.</td>', 'Wow! How do they know that these people will die in one  month? Amazing! LOL. I like the centered composition here, and the symmetry involved. The sky seems a little light and the statues a little dark, but nice eye for images.', '2003-08-25 13:07:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(398728, 34900, 10643, '<td valign="top">looking forward to the end of the challenge so I can read more about where this is. I had no idea he had such a monumental monumnet. The wispy clouds and the star glare are both nice touches adding to the spiritual and musical feel of the subject.</td>', 'looking forward to the end of the challenge so I can read more about where this is. I had no idea he had such a monumental monumnet. The wispy clouds and the star glare are both nice touches adding to the spiritual and musical feel of the subject.', '2003-08-25 13:29:49.000000', NULL, 1),
(398729, 34176, 10643, '<td valign="top">very moving. the crack along the face looks very much like a tear, so your title is right on.</td>', 'very moving. the crack along the face looks very much like a tear, so your title is right on.', '2003-08-25 13:30:33.000000', NULL, 1),
(398746, 34401, 7466, '<td valign="top">I don''t know that I like the snag in the foreground.  BTW, you might want to be really careful about using this shot anywhere.  I have heard that the city is really anal about who can photograph the sign and for what purpose.</td>', 'I don''t know that I like the snag in the foreground.  BTW, you might want to be really careful about using this shot anywhere.  I have heard that the city is really anal about who can photograph the sign and for what purpose.', '2003-08-25 13:53:54.000000', NULL, 1),
(398761, 34612, 7969, '<td valign="top">I like the luminescent feeling, esp in the bottom half of this shot. The bottom half has a ''glowing''  feeling to it.  While in some ways it is like a second image (which some may find distracting)  the leaves on top almost appear to be part of the actual monument vs. background.  They give it an enhanced ''roman'' feel IMO vs.  ''can/u.s'' feel.   I like the detail that your technique seems to enhanced, making an othewise flat image ''pop''.</td>', 'I like the luminescent feeling, esp in the bottom half of this shot. The bottom half has a ''glowing''  feeling to it.  While in some ways it is like a second image (which some may find distracting)  the leaves on top almost appear to be part of the actual monument vs. background.  They give it an enhanced ''roman'' feel IMO vs.  ''can/u.s'' feel.   I like the detail that your technique seems to enhanced, making an othewise flat image ''pop''.', '2003-08-25 14:22:27.000000', NULL, 1),
(398763, 34221, 7969, '<td valign="top">The lightening and the color of the sky contrasted with the white monu. is what works in this image IMO.  The tree is also composed in a way that does not distract from the image and adds to it IMO.</td>', 'The lightening and the color of the sky contrasted with the white monu. is what works in this image IMO.  The tree is also composed in a way that does not distract from the image and adds to it IMO.', '2003-08-25 14:23:48.000000', NULL, 1),
(398767, 34832, 7969, '<td valign="top">The composition is good here, and that you have eliminated any distracting features in a background is good, though I find the white to be very stark.</td>', 'The composition is good here, and that you have eliminated any distracting features in a background is good, though I find the white to be very stark.', '2003-08-25 14:25:11.000000', NULL, 1),
(398768, 34893, 7969, '<td valign="top">While generally I don''t like frames or strak white backgrounds, in this instance I think the frame helps to offset the starkness of the white.  I do quite like your compostion and choice of monuments  (i am partial to native folks : ) ).  Well done.</td>', 'While generally I don''t like frames or strak white backgrounds, in this instance I think the frame helps to offset the starkness of the white.  I do quite like your compostion and choice of monuments  (i am partial to native folks : ) ).  Well done.', '2003-08-25 14:26:57.000000', NULL, 1),
(398769, 34666, 7969, '<td valign="top">Good light and tones, dark bkgrd works for me.  Simple yet effective and technically well done.</td>', 'Good light and tones, dark bkgrd works for me.  Simple yet effective and technically well done.', '2003-08-25 14:27:58.000000', NULL, 1),
(398772, 34891, 7969, '<td valign="top">Well, the subject here is what gets you points, very interesting find.  Photographically though, might have worked better in portrait mode, hence blurring the distracting people and buildings in background.  May have tried to crop out the forground people a little more, esp the 1/2 guy and the peoples heads on the bottom.  just thoughts again nice find.</td>', 'Well, the subject here is what gets you points, very interesting find.  Photographically though, might have worked better in portrait mode, hence blurring the distracting people and buildings in background.  May have tried to crop out the forground people a little more, esp the 1/2 guy and the peoples heads on the bottom.  just thoughts again nice find.', '2003-08-25 14:31:42.000000', NULL, 1),
(398777, 34632, 327, '<td valign="top">Seems a little bit dark. Maybe my monitor.. I do love this shot, the composition is so nice. Well done.-8</td>', 'Seems a little bit dark. Maybe my monitor.. I do love this shot, the composition is so nice. Well done.-8', '2003-08-25 14:36:25.000000', NULL, 1),
(398779, 34828, 327, '<td valign="top">Nice clean, clear crisp shot. Good color light. I don''t like the crop/composition.</td>', 'Nice clean, clear crisp shot. Good color light. I don''t like the crop/composition.', '2003-08-25 14:37:10.000000', NULL, 1),
(398780, 34875, 327, '<td valign="top">Nicely done. Good color, light.</td>', 'Nicely done. Good color, light.', '2003-08-25 14:38:01.000000', NULL, 1),
(398781, 34869, 327, '<td valign="top">Nice work. I think the light is a little harsh or over exposed. However this is a good shot.</td>', 'Nice work. I think the light is a little harsh or over exposed. However this is a good shot.', '2003-08-25 14:39:35.000000', NULL, 1),
(398783, 34773, 772, '<td valign="top">very nice use of perspective and non-literal representation of your subject.. the background also adds a nice element to this shot... great work :) = 10</td>', 'very nice use of perspective and non-literal representation of your subject.. the background also adds a nice element to this shot... great work :) = 10', '2003-08-25 14:40:09.000000', NULL, 1),
(398784, 34813, 10643, '<td valign="top">I like this (partially because it reminds me of the place where I took my own monument shot). Nice trees and sky, nice composition and great focus. I would like to see the statues'' feet not cut off; it''s disconcerting not being able to see where they''re standing.</td>', 'I like this (partially because it reminds me of the place where I took my own monument shot). Nice trees and sky, nice composition and great focus. I would like to see the statues'' feet not cut off; it''s disconcerting not being able to see where they''re standing.', '2003-08-25 14:40:45.000000', NULL, 1),
(398785, 34221, 10643, '<td valign="top">great angle and lighting for a towering figure, beautiful color</td>', 'great angle and lighting for a towering figure, beautiful color', '2003-08-25 14:41:08.000000', NULL, 1),
(398786, 34727, 327, '<td valign="top">Very good shooting. Not as crisp as it could be, but a good shot.</td>', 'Very good shooting. Not as crisp as it could be, but a good shot.', '2003-08-25 14:41:31.000000', NULL, 1),
(398787, 34414, 10643, '<td valign="top">wonder if this is the same firefighter-on-a-ladder monument as the other shot? I like this one, very humanizing being able to see the detail in the sculpture.</td>', 'wonder if this is the same firefighter-on-a-ladder monument as the other shot? I like this one, very humanizing being able to see the detail in the sculpture.', '2003-08-25 14:42:32.000000', NULL, 1),
(398788, 34659, 11206, '<td valign="top">This is awesome.  What kind of memorial is this though.  I like it alot.</td>', 'This is awesome.  What kind of memorial is this though.  I like it alot.', '2003-08-25 14:43:59.000000', NULL, 1),
(398791, 34905, 11206, '<td valign="top">A bit dark in front but still a great picture.</td>', 'A bit dark in front but still a great picture.', '2003-08-25 14:46:22.000000', NULL, 1),
(398792, 34893, 11206, '<td valign="top">This is awesome.  I love the color and the pose of the monument!!</td>', 'This is awesome.  I love the color and the pose of the monument!!', '2003-08-25 14:47:31.000000', NULL, 1),
(398849, 34893, 10643, '<td valign="top">nice choice of color, and great composition. this would have suited negative space or the past as well.</td>', 'nice choice of color, and great composition. this would have suited negative space or the past as well.', '2003-08-25 16:17:31.000000', NULL, 1),
(398850, 34559, 10643, '<td valign="top">the bright red behind the totem pole is very striking, but it''s clashy and distracting. would be better to try this shot against a more neutral background, or even in black and white or duotone.</td>', 'the bright red behind the totem pole is very striking, but it''s clashy and distracting. would be better to try this shot against a more neutral background, or even in black and white or duotone.', '2003-08-25 16:18:08.000000', NULL, 1),
(398852, 34819, 10643, '<td valign="top">the angle of this shot is very disconcerting, not sure if that''s intentional or not. it makes the "groom" cow look very scary!</td>', 'the angle of this shot is very disconcerting, not sure if that''s intentional or not. it makes the "groom" cow look very scary!', '2003-08-25 16:18:47.000000', NULL, 1),
(398854, 34832, 10643, '<td valign="top">I''d like to see this with some background or a more interesting sky. there''s no sense of place or context as it is now. would also not crop off the basketball.</td>', 'I''d like to see this with some background or a more interesting sky. there''s no sense of place or context as it is now. would also not crop off the basketball.', '2003-08-25 16:19:24.000000', NULL, 1),
(398855, 34873, 10643, '<td valign="top">a neat statue, and good job capturing the water splashes.</td>', 'a neat statue, and good job capturing the water splashes.', '2003-08-25 16:19:48.000000', NULL, 1),
(398857, 34368, 10643, '<td valign="top">it was certainly too damn hot to go to the real Lincoln Memorial this weekend (trust me) ... nice workaround!</td>', 'it was certainly too damn hot to go to the real Lincoln Memorial this weekend (trust me) ... nice workaround!', '2003-08-25 16:21:36.000000', NULL, 1),
(398858, 34891, 10643, '<td valign="top">a very neat sculpture, never seen anything quite like it. looking forward to finding out where this is!</td>', 'a very neat sculpture, never seen anything quite like it. looking forward to finding out where this is!', '2003-08-25 16:22:02.000000', NULL, 1),
(398859, 34646, 10643, '<td valign="top">the odd angle adds drama and motion to what would otherwise be a very conventional photo. it''s almost like he''s about to walk out of the picture, an effect you couldn''t have gotten with a centered subject. very nice job.</td>', 'the odd angle adds drama and motion to what would otherwise be a very conventional photo. it''s almost like he''s about to walk out of the picture, an effect you couldn''t have gotten with a centered subject. very nice job.', '2003-08-25 16:23:04.000000', NULL, 1),
(398861, 34773, 10643, '<td valign="top">striking and emotional, lots of meaning here</td>', 'striking and emotional, lots of meaning here', '2003-08-25 16:23:40.000000', NULL, 1),
(398862, 34557, 9411, '<td valign="top">Wow,, what an outstanding rendering of an incredibly moving memorial. This incident is one of those that is little known outside of Europe. Thank you for entering a very moving image. 9</td>', 'Wow,, what an outstanding rendering of an incredibly moving memorial. This incident is one of those that is little known outside of Europe. Thank you for entering a very moving image. 9', '2003-08-25 16:24:13.000000', NULL, 1),
(398863, 34137, 10643, '<td valign="top">the people (and their cute hats) add much-needed scale to this. glad they''re there!</td>', 'the people (and their cute hats) add much-needed scale to this. glad they''re there!', '2003-08-25 16:24:20.000000', NULL, 1),
(398864, 34877, 10643, '<td valign="top">Outstanding! This has that "wow" factor and is easily one of my favorites this challenge. Using the scoreboard as a backdrop is inspired.</td>', 'Outstanding! This has that "wow" factor and is easily one of my favorites this challenge. Using the scoreboard as a backdrop is inspired.', '2003-08-25 16:25:36.000000', NULL, 1),
(398865, 34443, 10643, '<td valign="top">now how can they prove it was the first chicken sandwich?! a funny and clever take on "monuments" :)</td>', 'now how can they prove it was the first chicken sandwich?! a funny and clever take on "monuments" :)', '2003-08-25 16:26:53.000000', NULL, 1),
(398866, 34894, 10643, '<td valign="top">I''m not usually crazy about dead-center subjects but the lines of this monument are so strong as to demand it. only wish the trees/sky were more symmetrical and there weren''t all those pesky people messing up such a striking picture! (none of which is your fault or affecting my score)</td>', 'I''m not usually crazy about dead-center subjects but the lines of this monument are so strong as to demand it. only wish the trees/sky were more symmetrical and there weren''t all those pesky people messing up such a striking picture! (none of which is your fault or affecting my score)', '2003-08-25 16:27:59.000000', NULL, 1),
(398867, 34837, 10643, '<td valign="top">simple and careful composition, well-suited to the subject. would like to see a slightly deeper depth of field (no pun intended) and a low horizon without the hill in the background</td>', 'simple and careful composition, well-suited to the subject. would like to see a slightly deeper depth of field (no pun intended) and a low horizon without the hill in the background', '2003-08-25 16:28:53.000000', NULL, 1),
(398869, 34863, 10643, '<td valign="top">One of my favorites this challenge, very nice job</td>', 'One of my favorites this challenge, very nice job', '2003-08-25 16:29:38.000000', NULL, 1),
(398872, 34713, 10643, '<td valign="top">such a wonderful blue Western sky really adds to this. nice shot!</td>', 'such a wonderful blue Western sky really adds to this. nice shot!', '2003-08-25 16:31:00.000000', NULL, 1),
(398873, 34875, 10643, '<td valign="top">I love this spot at sunset. nice job, very warm and subtle photo.</td>', 'I love this spot at sunset. nice job, very warm and subtle photo.', '2003-08-25 16:31:47.000000', NULL, 1),
(398886, 34807, 1143, '<td valign="top">whoaaaaaaa.. i think you''re tilting to the left a little.. or is it just an illusion?<br/>i love night shots and this one is lovely. nice contrast with the black and yellow. shutter could''ve been a tad faster maybe.</td>', 'whoaaaaaaa.. i think you''re tilting to the left a little.. or is it just an illusion?i love night shots and this one is lovely. nice contrast with the black and yellow. shutter could''ve been a tad faster maybe.', '2003-08-25 16:45:00.000000', NULL, 1),
(398891, 34897, 4210, '<td valign="top">I like the statement it makes, but the rust spot, and the dark foliage in the background are quite distracting.</td>', 'I like the statement it makes, but the rust spot, and the dark foliage in the background are quite distracting.', '2003-08-25 16:49:26.000000', NULL, 1),
(398894, 34911, 4210, '<td valign="top">Interesting. I would have shot from a different angle to make the foot less recognizable.</td>', 'Interesting. I would have shot from a different angle to make the foot less recognizable.', '2003-08-25 16:50:09.000000', NULL, 1),
(398897, 34665, 4210, '<td valign="top">Great colour. The trees really give the statue presence.</td>', 'Great colour. The trees really give the statue presence.', '2003-08-25 16:50:49.000000', NULL, 1),
(398904, 34115, 4210, '<td valign="top">Great colour, details and texture.</td>', 'Great colour, details and texture.', '2003-08-25 16:58:21.000000', NULL, 1),
(398905, 34832, 4210, '<td valign="top">Interesting colour, negative space and use of vertical space.</td>', 'Interesting colour, negative space and use of vertical space.', '2003-08-25 16:59:15.000000', NULL, 1),
(398908, 34491, 4210, '<td valign="top">Could use a tasteful boader, simply becasue the composition is so tight.</td>', 'Could use a tasteful boader, simply becasue the composition is so tight.', '2003-08-25 17:00:14.000000', NULL, 1),
(398911, 34318, 4210, '<td valign="top">I have no idea what it is, but I really really like it.</td>', 'I have no idea what it is, but I really really like it.', '2003-08-25 17:00:39.000000', NULL, 1),
(398913, 34318, 1143, '<td valign="top">I love the contrast and the lines. Very cool shot. I''ll take your word that it''s a monument because I can''t tell what the heck it is.  10</td>', 'I love the contrast and the lines. Very cool shot. I''ll take your word that it''s a monument because I can''t tell what the heck it is.  10', '2003-08-25 17:01:20.000000', NULL, 1),
(398914, 34748, 5391, '<td valign="top">The shadow hurts this otherwise beautiful shot.  I like your sky in the background and the way the dam really feels "big".</td>', 'The shadow hurts this otherwise beautiful shot.  I like your sky in the background and the way the dam really feels "big".', '2003-08-25 17:01:59.000000', NULL, 1),
(398915, 34538, 1143, '<td valign="top">Great perspective. I really like the lines and negative space. Nice night shot. 9</td>', 'Great perspective. I really like the lines and negative space. Nice night shot. 9', '2003-08-25 17:02:17.000000', NULL, 1),
(398916, 34909, 11188, '<td valign="top">Interesting shot - although personally I feel that the clouds became the focal pointwith the memorial obscured as just an outline.</td>', 'Interesting shot - although personally I feel that the clouds became the focal pointwith the memorial obscured as just an outline.', '2003-08-25 17:02:57.000000', NULL, 1),
(398917, 34867, 1143, '<td valign="top">This is just a very cool building. I think you cropped a bit tight. The blue buildings on the left really add to the geometric feel and go well with the blue sky.. could''ve shown a bit more of them. 8</td>', 'This is just a very cool building. I think you cropped a bit tight. The blue buildings on the left really add to the geometric feel and go well with the blue sky.. could''ve shown a bit more of them. 8', '2003-08-25 17:04:11.000000', NULL, 1),
(398918, 34491, 1143, '<td valign="top">Very nice job with the exposure! I like the angle. If at all possible, it might be worth trying to hold a solid background behind her. Good work with the dof, but it blends so well with the sculpture still. 7</td>', 'Very nice job with the exposure! I like the angle. If at all possible, it might be worth trying to hold a solid background behind her. Good work with the dof, but it blends so well with the sculpture still. 7', '2003-08-25 17:05:28.000000', NULL, 1),
(398919, 34837, 1143, '<td valign="top">I really like the dof. Great focus on the foreground. I might like a little less of a straight perspective so that the crosses further down are a little more separate. I''m also not sure about the crop on top.. seems a bit tight maybe. 7</td>', 'I really like the dof. Great focus on the foreground. I might like a little less of a straight perspective so that the crosses further down are a little more separate. I''m also not sure about the crop on top.. seems a bit tight maybe. 7', '2003-08-25 17:07:14.000000', NULL, 1),
(398932, 34877, 7969, '<td valign="top">I wonder if you took a step to the left, to get only the score board in the background how it would be.  I think you would have a much stronger image, perhaps try cropping out the ''lines'' on the sides?</td>', 'I wonder if you took a step to the left, to get only the score board in the background how it would be.  I think you would have a much stronger image, perhaps try cropping out the ''lines'' on the sides?', '2003-08-25 17:24:01.000000', NULL, 1),
(398933, 34538, 7969, '<td valign="top">Not sure if these buildings are actually monuments, but I think it is a wonderful shot.  The blacks and grays and lighting are great.  Compostion is also good.</td>', 'Not sure if these buildings are actually monuments, but I think it is a wonderful shot.  The blacks and grays and lighting are great.  Compostion is also good.', '2003-08-25 17:25:53.000000', NULL, 1),
(398936, 34874, 6624, '<td valign="top">well presented statue...meets the challenge and is a powerful reminder of who and what our fire fighters are</td>', 'well presented statue...meets the challenge and is a powerful reminder of who and what our fire fighters are', '2003-08-25 17:27:05.000000', NULL, 1),
(398937, 34869, 7969, '<td valign="top">Clean, clear shot, would like to see it a tiny bit darker to remove (maybe) a little of the glare on her chest.  But overall pretty good.</td>', 'Clean, clear shot, would like to see it a tiny bit darker to remove (maybe) a little of the glare on her chest.  But overall pretty good.', '2003-08-25 17:27:07.000000', NULL, 1),
(398938, 34414, 6624, '<td valign="top">nice textures and the motion comes across - powerful statue as well</td>', 'nice textures and the motion comes across - powerful statue as well', '2003-08-25 17:27:31.000000', NULL, 1),
(398939, 34557, 7969, '<td valign="top">Good composition, certainly a unique monument.</td>', 'Good composition, certainly a unique monument.', '2003-08-25 17:28:03.000000', NULL, 1),
(398941, 34875, 7969, '<td valign="top">The lighting is its strong point for sure,  if I were to be really picky I might like it with out the tree on the right better,  though it may help to frame it.  nice job.</td>', 'The lighting is its strong point for sure,  if I were to be really picky I might like it with out the tree on the right better,  though it may help to frame it.  nice job.', '2003-08-25 17:29:21.000000', NULL, 1),
(398945, 34632, 7969, '<td valign="top">Good perspective  and composition lighting is good. Looks like could be a tourist postcard.</td>', 'Good perspective  and composition lighting is good. Looks like could be a tourist postcard.', '2003-08-25 17:30:52.000000', NULL, 1),
(398950, 34532, 7969, '<td valign="top">My choice for first place, the compostion is very good, lighting is soft and warm. Evokes of feeling of times past, an extremely well done photo overall.  congratulations.  I can see why you had to leave it for perspective, but if i were to be very critical I would say should of cropped or moved the (garbage can?) in the bottom right corner.</td>', 'My choice for first place, the compostion is very good, lighting is soft and warm. Evokes of feeling of times past, an extremely well done photo overall.  congratulations.  I can see why you had to leave it for perspective, but if i were to be very critical I would say should of cropped or moved the (garbage can?) in the bottom right corner.', '2003-08-25 17:34:46.000000', NULL, 1),
(398953, 34820, 7969, '<td valign="top">I like the dark against the blues, I am curious how would be if shot it from lying on ground, so only see the sky, I find the other parts of your back ground a bit distracting, from the otherwise strong and powerful image.</td>', 'I like the dark against the blues, I am curious how would be if shot it from lying on ground, so only see the sky, I find the other parts of your back ground a bit distracting, from the otherwise strong and powerful image.', '2003-08-25 17:38:54.000000', NULL, 1),
(398957, 34646, 7969, '<td valign="top">nice work on getting him to really seem like he is moving, I think the camera tilt really helped bring this one to life.  Too bad they stuck the park benches there :  ), but I realize you could not have moved them  lol.</td>', 'nice work on getting him to really seem like he is moving, I think the camera tilt really helped bring this one to life.  Too bad they stuck the park benches there :  ), but I realize you could not have moved them  lol.', '2003-08-25 17:41:05.000000', NULL, 1),
(398961, 34789, 11034, '<td valign="top">What happen on 9-11-03? Did you mean 2001?</td>', 'What happen on 9-11-03? Did you mean 2001?', '2003-08-25 17:42:41.000000', NULL, 1),
(398972, 34889, 7969, '<td valign="top">A straight shot, not very creative in presentation, but technically very well done, so will probably do very well in challenge, the tones of the monument are capptured beautifully, sky and tree color is good.  I do not like the whiteness on the bottom part-- I find it quite distracting to the otherwise warm tones.  but what do i know.</td>', 'A straight shot, not very creative in presentation, but technically very well done, so will probably do very well in challenge, the tones of the monument are capptured beautifully, sky and tree color is good.  I do not like the whiteness on the bottom part-- I find it quite distracting to the otherwise warm tones.  but what do i know.', '2003-08-25 17:46:35.000000', NULL, 1),
